var i=`0457-mant`;var t=`world-0457`;var o=`TR`;var l=`western-asia`;var a=4;var g=72;var r={en:`Mantı`,ua:`Манти`};var s={en:`A traditional dish from Türkiye, centered on all-purpose flour, chicken egg, ground beef, yellow onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: пшеничне борошно універсальне, куряче яйце, яловичий фарш, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 20 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 20 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:20,i:[[`all-purpose-flour`,390,`g`],[`chicken-egg`,1,`pcs`],[`water`,150,`ml`],[`table-salt`,6,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:8,i:[[`ground-beef`,430,`g`],[`yellow-onion`,220,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Roll the rested dough thinly, cut rounds, place filling in the center and pinch each dumpling tightly closed.`,ua:`Тонко розкачайте відпочиле тісто, виріжте кружальця, викладіть начинку в центр і ретельно заліпіть краї кожного вареника чи пельменя.`,t:[`rolling-out-dough`,`pinching-dumplings`],m:26,i:[]},{en:`Pinch the tiny mantı parcels tightly and boil gently until the minced meat inside is fully cooked.`,ua:`Щільно защипніть маленькі манти й обережно відварюйте до повної готовності м’ясної начинки.`,t:[`boiling`],m:13,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:5,i:[[`plain-yogurt`,280,`g`],[`garlic`,3,`clove`],[`unsalted-butter`,45,`g`],[`hot-paprika`,4,`g`]]}];var d={slug:i,id:t,country:`TR`,region:l,servings:4,minutes:72,title:r,text:s,steps:u};export{o as country,d as default,t as id,g as minutes,l as region,a as servings,i as slug,u as steps,s as text,r as title};